const results = items[0].json.rows || [];
let table = '| URL | Clicks | Impressions | CTR | Position |\n|---|---|---|---|---|\n';
results.slice(0, 10).forEach(row => {
  table += `| ${row.keys[0]} | ${row.clicks} | ${row.impressions} | ${(row.ctr * 100).toFixed(2)}% | ${row.position.toFixed(1)} |\n`;
});
return { table };

